function Playbooks({clientId}:{clientId:number}){
 const [items,setItems]=useState<Array<{id:number;kind:string;title:string;content:string;url:string|null;tag:string|null}>>([]),[steps,setSteps]=useState<Array<{id:number;title:string;status:string}>>([]),[kind,setKind]=useState("template"),[title,setTitle]=useState(""),[content,setContent]=useState(""),[url,setUrl]=useState("");
 const refresh=useCallback(async()=>{if(!clientId)return;const r=await fetch("/api/playbooks?clientId="+clientId);if(r.ok){const v=await r.json();setItems(v.items);setSteps(v.steps)}},[clientId]);useEffect(()=>{refresh()},[refresh]);
 async function save(e:React.FormEvent){e.preventDefault();if(!title.trim())return;const r=await fetch("/api/playbooks",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({clientId,kind,title,content,url,tag:kind==="template"?"Reusable":"Client asset"})});if(r.ok){setTitle("");setContent("");setUrl("");await refresh()}}
 async function toggle(id:number,status:string){await fetch("/api/playbooks",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({clientId,id,status:status==="done"?"pending":"done"})});await refresh()}
 const guides=[{signal:"Reply rate below 0.5%",title:"Campaigns are not getting replies?",cause:"Likely deliverability or spam placement",action:"Pause scaling. Check inbox placement, domains, copy risk and sending health before changing the offer.",steps:["Check SPF, DKIM, DMARC and inbox placement","Review bounce rate and mailbox health","Remove risky copy before changing the offer"]},{signal:"Replies above 0.5%, no opportunities",title:"Replies, but no qualified interest?",cause:"Usually the list or offer",action:"Review ICP fit, pain relevance and whether the promised outcome is strong enough for this audience.",steps:["Audit 20 replies for repeated objections","Compare the list against the real buying trigger","Rewrite the offer around one measurable outcome"]},{signal:"Opportunities, no meetings",title:"Positive replies are not converting into a meeting?",cause:"Speed-to-lead, follow-up or weak CTA",action:"Respond inside five minutes, give a concrete reason to meet and run 3–7 follow-ups. Most teams stop after two.",steps:["Reply within five minutes","Use a low-friction, specific CTA","Run 3–7 human follow-ups before closing the loop"]},{signal:"Meetings booked, low show rate",title:"People book but do not show?",cause:"Reminder and nurture gap",action:"Use calendar reminders, a 30-minute agenda message and a relevant VSL, case study or teardown before the call.",steps:["Confirm the agenda immediately","Send a relevant proof asset before the call","Run 24-hour and 30-minute reminders"]}];
 return <div className="playbookHub"><section className="diagnosticHeader"><span>DIAGNOSTIC PLAYBOOK</span><h2>Find the bottleneck before changing the campaign.</h2><p>Follow the funnel in order. Open a playbook for the checks and next actions.</p></section><div className="diagnosticGrid">{guides.map((g,i)=><details key={g.title}><summary><b>0{i+1} · {g.signal}</b><h3>{g.title}</h3><strong>{g.cause}</strong><p>{g.action}</p><em>Open playbook ↓</em></summary><ol>{g.steps.map(step=><li key={step}>{step}</li>)}</ol></details>)}</div><details className="salesFramework"><summary><span>05 · SALES CONVERSION</span><h2>Can’t close at the target price—or prospects stall after the first meeting?</h2><strong>Use the Discovery → Growth Plan → Decision framework</strong><em>Open full sales playbook ↓</em></summary><div className="salesFrameworkBody"><section><b>CALL 1</b><h3>Discovery call</h3><p>This discovery determines most of whether the deal closes. Diagnose before presenting.</p><ol><li>What is their goal—the North Star outcome they want to accomplish?</li><li>What problems or blockers prevent that outcome?</li><li>What constraints are they operating under?</li><li>What are they doing now, what have they tried, and what worked or failed?</li><li>How does the business change if they achieve the goal? What will it allow them to do?</li><li>What happens if they do not accomplish it?</li><li>If we can help reach that outcome, are they willing to take action?</li><li>Collect the KPIs and numbers needed to quantify the transformation.</li></ol><blockquote>“You’re a fit for our solution. We’d like to create a custom growth plan showing how you can reach [their outcome]. Does that sound good?”</blockquote><p><b>Must:</b> book the next call while you are still on this call. Offer two concrete times. Do not leave scheduling to email or LinkedIn.</p></section><section><b>CALL 2</b><h3>Custom growth plan</h3><p>Treat every opportunity like a $1B deal. Present a professional roadmap before discussing the product or service.</p><ul><li><b>Case studies:</b> proof relevant to their situation.</li><li><b>Expected outcome:</b> business results, not features.</li><li><b>How it works:</b> simple steps proving you understand their world and the method to reach the outcome.</li><li><b>Market alternatives:</b> two other paths, including their real cost and trade-offs.</li><li><b>Revenue growth:</b> model the transformation using numbers collected during discovery—without making unsupported promises.</li><li><b>What we do vs. what they do:</b> show the complete value stack, individual component costs, responsibilities, and why the combined plan is more efficient.</li><li><b>Before pricing:</b> confirm the plan makes sense and ask how they see it working in their business.</li><li><b>Product walkthrough:</b> keep it visual and under five minutes.</li><li><b>Pricing:</b> present at least three options.</li></ul><p><b>Must:</b> book the decision call before ending. Position it as the session where you show exactly how implementation works for whichever plan they prefer.</p></section><section><b>CALL 3</b><h3>Decision and implementation</h3><p>Present the exact steps that begin after signature: ownership, timeline, deliverables, milestones, and what they should expect.</p><ul><li>Bring required partners or decision-makers into the call.</li><li>Resolve objections without pressure—sales means helping them make a sound decision.</li><li>If price resistance is really a trust gap, offer a pilot or front-end offer that proves value first.</li><li>Always leave the next action, owner, and date explicit.</li></ul></section><aside><b>PRO TIP</b><h3>Help outside the script.</h3><p>Share useful ideas, examples, and what has worked elsewhere. Be creative about how they can apply it in their business. Human, practical help builds more trust than “full-focus sales” and can materially improve close rates.</p></aside></div></details><div className="playbookColumns"><section className="libraryPanel"><header><div><span>REUSABLE LIBRARY</span><h2>Winning templates, angles, CTAs and assets</h2></div></header><form className="playbookForm" onSubmit={save}><select value={kind} onChange={e=>setKind(e.target.value)}><option value="template">Sub-sequence / CTA</option><option value="angle">Campaign angle</option><option value="asset">Asset or guide</option></select><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. This CTA booked meetings"/><textarea value={content} onChange={e=>setContent(e.target.value)} placeholder="Paste the CTA, follow-up sequence, angle, notes or instructions…"/><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="Optional asset link"/><button>Save to library</button></form><div className="libraryRows">{items.map(item=><article key={item.id}><span>{item.kind}</span><div><strong>{item.title}</strong><p>{item.content||"No notes added."}</p>{item.url&&<a href={item.url} target="_blank" rel="noreferrer">Open asset ↗</a>}</div></article>)}{!items.length&&<p className="empty">Save your first winning CTA, angle or client asset.</p>}</div></section><aside className="roadmapPanel"><span>CLIENT ROADMAP</span><h2>What is done and what happens next</h2><p>Clients can always see project progress.</p>{steps.map(step=><button className={step.status==="done"?"done":""} key={step.id} onClick={()=>toggle(step.id,step.status)}><i>{step.status==="done"?"✓":""}</i><span>{step.title}</span></button>)}<small>{steps.filter(s=>s.status==="done").length} of {steps.length} complete</small></aside></div></div>
}
function DealEditor({prospect,save}:{prospect:Prospect;save:(id:number,value:number,booked:string,showed:string,closed:string)=>Promise<boolean>}){
 const[value,setValue]=useState(String((prospect.deal_value_cents??0)/100)),[booked,setBooked]=useState(prospect.meeting_booked_at?.slice(0,10)??''),[showed,setShowed]=useState(prospect.showed_at?.slice(0,10)??''),[closed,setClosed]=useState(prospect.expected_close_date?.slice(0,10)??''),[saving,setSaving]=useState(false);
 useEffect(()=>{setValue(String((prospect.deal_value_cents??0)/100));setBooked(prospect.meeting_booked_at?.slice(0,10)??'');setShowed(prospect.showed_at?.slice(0,10)??'');setClosed(prospect.expected_close_date?.slice(0,10)??'')},[prospect.id,prospect.deal_value_cents,prospect.meeting_booked_at,prospect.showed_at,prospect.expected_close_date]);
 const isClosed=prospect.pipeline_tag==='closed_won',hasShown=isClosed||prospect.pipeline_tag==='showed';
 return <section className="dealEditor"><div><span>MEETING BOOKED DATE</span><input type="date" value={booked} onChange={e=>setBooked(e.target.value)}/></div>{hasShown&&<div><span>SHOW-UP DATE</span><input type="date" value={showed} onChange={e=>setShowed(e.target.value)}/></div>}{isClosed&&<><div><span>ACTUAL CLOSE DATE</span><input type="date" value={closed} onChange={e=>setClosed(e.target.value)}/></div><div><span>NEW MRR</span><label><b>$</b><input type="number" min="0" step="100" value={value} onChange={e=>setValue(e.target.value)}/></label></div></>}<button disabled={saving} onClick={async()=>{setSaving(true);await save(prospect.id,Number(value)||0,booked,showed,closed);setSaving(false)}}>{saving?'Saving…':'Save funnel details'}</button></section>
}
function Queue({title,children}:{title:string;children:React.ReactNode}){return <section className="queue"><h2>{title}</h2>{children}</section>}
function Prospects({items,open,move}:{items:Prospect[];open:(id:number)=>void;move:(id:number,status:string)=>void}){
 const[search,setSearch]=useState(''),[tag,setTag]=useState('all'),query=search.trim().toLowerCase();
 const tagOf=(p:Prospect)=>p.pipeline_tag||(['meeting_booked','showed','closed_won'].includes(p.status)?p.status:'opportunity');
 const labels:Record<string,string>={opportunity:'Opportunity',meeting_booked:'Meeting booked',showed:'Showed up',closed_won:'Closed won'};
 const visible=items.filter(p=>(tag==='all'||tagOf(p)===tag)&&(!query||[p.first_name,p.last_name,p.email,p.company_name,p.company_domain,p.campaign_name].some(value=>String(value??'').toLowerCase().includes(query))));
 return <><div className="crmToolbar"><p className="crmHint">One opportunity database. Smartlead supplies opportunities and campaigns; internal tags track booked, showed and won.</p><div className="crmFilters"><select value={tag} onChange={e=>setTag(e.target.value)}><option value="all">All opportunity tags</option>{Object.entries(labels).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search name, company, email, domain or campaign…" aria-label="Search leads and CRM"/></div></div><section className="opportunityDatabase"><header><div><span>SMARTLEAD OPPORTUNITIES</span><h2>{visible.length} leads</h2></div><small>Each lead stays attributed to its original campaign</small></header><div className="opportunityRows">{visible.map(p=><article key={p.id}><button className="opportunityIdentity" onClick={()=>open(p.id)}><i>{initials(p.first_name,p.last_name)}</i><span><strong>{p.first_name} {p.last_name}</strong><small>{p.company_name}{p.company_domain?` · ${p.company_domain}`:''}</small><em>{p.email}</em><em>{p.campaign_name??'Campaign unavailable'}{p.reply_category?` · ${p.reply_category}`:''}</em></span></button><select className={`opportunityTag ${tagOf(p)}`} value={tagOf(p)} onChange={e=>move(p.id,e.target.value)} aria-label={`Tag ${p.first_name} ${p.last_name}`}><option value="opportunity">Opportunity</option><option value="meeting_booked">Meeting booked</option><option value="showed">Showed up</option><option value="closed_won">Closed won</option></select><span className="opportunityValue">{p.deal_value_cents?`$${n(Math.round(p.deal_value_cents/100))}`:'No New MRR'}<small>{p.expected_close_date?new Date(`${p.expected_close_date}T00:00:00`).toLocaleDateString():'No date'}</small></span><button className="opportunityEdit" onClick={()=>open(p.id)}>Edit →</button></article>)}{visible.length===0&&<p className="empty large">No Smartlead opportunities match this search and tag.</p>}</div></section></>
}
const n=(value:number|undefined)=>new Intl.NumberFormat("en-US").format(value??0);
const jsonObject=(value:unknown):Record<string,number>=>{if(value&&typeof value==='object'&&!Array.isArray(value))return value as Record<string,number>;if(typeof value==='string')try{const parsed=JSON.parse(value);return parsed&&typeof parsed==='object'?parsed:{}}catch{return{}}return{}};
const stepLabels:Record<string,string>={tam_reuse:"Reuse client TAM",source_shortfall:"Source shortfall only",deduplicate:"Deduplicate",qualify:"Apply ICP + exclusions",enrich:"Find missing emails",verify:"Verify eligible contacts",approve_export:"Approve Smartlead-ready list"};
function ListBuilder({data,clients,clientId,changeClient,createClient,canManage,rotateClientKey,setClientKey}:{data:TamData|null;clients:ClientWorkspace[];clientId:number;changeClient:(id:number)=>void;createClient:()=>void;canManage:boolean;rotateClientKey:()=>void;setClientKey:(apiKey:string)=>Promise<boolean>}){
 const job=data?.jobs[0],m=job?jsonObject(job.metrics_json):null;
 const [segmentView,setSegmentView]=useState<{name:string;companies:Array<{id:number;name:string;domain:string;icp_status:string}>}|null>(null),[segmentLoading,setSegmentLoading]=useState(false),[apiKeyInput,setApiKeyInput]=useState('');
 const viewSegment=async(id:number)=>{setSegmentLoading(true);const response=await fetch(`/api/tam/segment?clientId=${clientId}&segmentId=${id}`);if(response.ok){const value=await response.json();setSegmentView({name:value.segment.name,companies:value.companies})}setSegmentLoading(false)};
 if(!data)return <div className="empty large">Preparing the client TAM…</div>;
 return <div className="listBuilder">
  <section className="workspaceSelector"><div><span>CLIENT TAM WORKSPACE</span><h2>{data.client.name}</h2><p>Companies, contacts, imports and segments below belong only to this client.</p></div>{canManage&&<div><select value={clientId} onChange={e=>changeClient(Number(e.target.value))}>{clients.map(client=><option value={client.id} key={client.id}>{client.name} · {n(client.companies)} companies</option>)}</select><input type="password" value={apiKeyInput} onChange={e=>setApiKeyInput(e.target.value)} placeholder="Paste existing TAM API key" aria-label="Existing TAM API key"/><button onClick={async()=>{if(await setClientKey(apiKeyInput))setApiKeyInput('')}}>⌁ Save API key</button><button onClick={createClient}>＋ Create client workspace</button><button onClick={rotateClientKey}>↻ Rotate API key</button>{data.client.name.toLowerCase()!=='venluto'&&<a className="quietDanger deleteWorkspaceLink" href="#delete-workspace-confirm">Delete workspace</a>}</div>}</section>
  {canManage&&data.client.name.toLowerCase()!=='venluto'&&<div id="delete-workspace-confirm" className="nativeDeleteModal" role="dialog" aria-modal="true" aria-labelledby="delete-workspace-title"><a className="nativeDeleteBackdrop" href="#" aria-label="No, keep workspace"></a><section className="credentialCard deleteWorkspaceCard"><span>REMOVE CLIENT WORKSPACE</span><h2 id="delete-workspace-title">Delete {data.client.name}?</h2><p>Are you sure you want to delete this client workspace? Its login and Claude API key will stop working. Historical data will be archived safely.</p><div className="deleteWorkspaceActions"><a className="credentialDone nativeNoButton" href="#">No</a><form method="post" action="/api/clients/delete"><input type="hidden" name="clientId" value={data.client.id}/><button type="submit" className="confirmDelete">Yes, delete</button></form></div></section></div>}
  <section className="tamHero"><div><span className="tamLabel">MASTER TAM · {data.client.name}</span><h2>{n(data.counts.companies)} companies, kept for every future offer.</h2><p>One permanent source of truth. Claude can narrow it into sub-niches, attach public evidence and save reusable segments without re-importing the TAM.</p></div><div className="tamHeroTools"><a className="tamDownload" href={`/api/tam/export?clientId=${data.client.id}`}>↓ Download Master TAM CSV</a><div className="claudeLive"><span></span><div><strong>Claude API ready</strong><small>Locked to {data.client.name}</small></div></div></div></section>
  <div className="tamStats compact"><article><small>Companies</small><strong>{n(data.counts.companies)}</strong></article><article><small>Contacts</small><strong>{n(data.counts.contacts)}</strong></article></div>
  {(data.segments?.length>0||data.imports?.length>0)&&<section className="tamLibrary"><div><span>SEGMENTS</span><h2>Reusable slices of this TAM</h2><div className="segmentRows">{data.segments.map(s=><article key={s.id}><div><strong>{s.name}</strong><small>Saved audience segment</small></div><b>{n(s.company_count)} companies</b><button onClick={()=>viewSegment(s.id)}>View →</button></article>)}</div>{segmentLoading&&<p className="empty">Loading segment companies…</p>}{segmentView&&<div className="segmentPreview"><header><div><span>SEGMENT PREVIEW</span><h3>{segmentView.name}</h3></div><button onClick={()=>setSegmentView(null)}>Close</button></header><div>{segmentView.companies.map(company=><article key={company.id}><strong>{company.name||company.domain}</strong><small>{company.domain}</small><em>{company.icp_status}</em></article>)}</div><small>Showing the first {n(segmentView.companies.length)} companies.</small></div>}</div><div><span>RECENT IMPORTS</span>{data.imports.slice(0,4).map(batch=><article key={batch.id}><strong>{batch.label}</strong><small>{n(batch.received_count)} reconciled · {batch.status}</small></article>)}</div></section>}
  {job&&m&&<><section className="jobTop"><div><span className="readyPill">READY FOR APPROVAL</span><h2>{job.name}</h2><p>{job.broad_icp} · {job.target_titles.join(", ")}</p></div><div className="readyCount"><strong>{n(m.ready)}</strong><span>of {n(job.desired_count)} ready</span></div></section>
   <div className="reuseBanner"><div><strong>{n(m.existingReady)} reused</strong><span>from the client TAM</span></div><b>＋</b><div><strong>{n(m.shortfall)} sourced</strong><span>only to fill the gap</span></div><div className="savings"><strong>{n(m.apiCallsAvoided)} calls avoided</strong><span>${m.costAvoidedUsd} estimated provider cost saved</span></div></div>
   <section className="funnelCard"><div className="funnelHead"><div><span>JOB FUNNEL</span><h2>Every reduction has a reason.</h2></div><div><strong>{Math.floor((m.actualSeconds??0)/60)}m {(m.actualSeconds??0)%60}s</strong><small>request → ready list</small></div></div><div className="funnelSteps">{(job.steps??[]).map((s,index)=>{const losses=jsonObject(s.loss_reasons_json);return <article key={s.id}><div className="stepIndex">{index+1}</div><div className="stepBody"><div><strong>{stepLabels[s.step_key]??s.step_key}</strong><span className="stepDone">✓ complete</span></div><div className="stepCounts"><b>{n(s.input_count)}</b><span>in</span><i>→</i><b>{n(s.output_count)}</b><span>out</span>{s.api_calls>0&&<em>{n(s.api_calls)} API calls</em>}</div>{Object.keys(losses).length>0&&<p>{Object.entries(losses).map(([reason,count])=>`${n(count)} ${reason.replaceAll('_',' ')}`).join(" · ")}</p>}</div></article>})}</div></section>
   <section className="exportCard"><div><span className="exportIcon">✓</span><div><strong>{n(job.export?.contact_count)} contacts approved</strong><p>Smartlead-ready list recorded. Exact contact IDs are preserved in this job; live upload is disabled.</p></div></div><button disabled>Upload disabled in demo</button></section></>}
  <section className="tamFoot"><div><strong>Claude Code API</strong><span>Authenticated, machine-readable TAM, batches, job checkpoints and export history.</span></div><code>GET /api/internal/tam</code></section>
 </div>
}
function Integrations({errors,retry,dismiss}:{errors:SyncError[];retry:(id:number)=>void;dismiss:(id:number)=>void}){const stamp=(date:string)=>{const parsed=new Date(date);return Number.isNaN(parsed.getTime())?'Time unavailable':parsed.toLocaleString()};return <><div className="integrationCards">{['Smartlead','Close','Cal.com'].map((name,i)=><article key={name}><span className={`health ${errors.some(e=>e.provider.toLowerCase()===name.toLowerCase())?'warn':''}`}></span><div><strong>{name}</strong><small>{errors.some(e=>e.provider.toLowerCase()===name.toLowerCase())?'Needs attention':'Webhook healthy'}</small></div><em>{i===0?'Reply ingestion':i===1?'Prospect sync':'Booking reconciliation'}</em></article>)}</div><div className="tableCard"><div className="tableToolbar"><strong>Failed syncs</strong><span>Retry current failures or dismiss stale test errors</span></div>{errors.length===0?<p className="empty large">No failed syncs. Everything is caught up.</p>:<div className="errorList">{errors.map(e=><article key={e.id}><span className="metricIcon red">×</span><div><strong>{e.provider} · {e.operation.replaceAll('_',' ')}</strong><p>{e.last_error}</p><small>{e.attempts} attempts · {stamp(e.updated_at)}</small></div><div className="errorActions"><button onClick={()=>retry(e.id)}>Retry safely</button><button className="dismissError" onClick={()=>dismiss(e.id)}>Dismiss</button></div></article>)}</div>}</div></>}
